import io
from rich.console import Console
from rich.prompt import Prompt, InvalidResponse

def test_custom_markup_error():
    INPUT = "invalid\nvalid"
    console = Console(file=io.StringIO(), markup=False)

    class MarkupPrompt(Prompt):
        def process_response(self, value):
            if value == "invalid":
                raise InvalidResponse("[red]Invalid input![/red]")
            return value

    prompt = MarkupPrompt("Enter name", console=console)
    prompt(stream=io.StringIO(INPUT))

    output = console.file.getvalue()
    print(f"Output: {repr(output)}")

    # If markup=False in Console and we don't pass markup=True to print(), 
    # we expect to see the raw markup tags.
    assert "[red]Invalid input![/red]" in output

if __name__ == "__main__":
    try:
        test_custom_markup_error()
        print("Test failed (markup was processed, but it should have been raw)!")
    except AssertionError:
        print("Test passed (markup was raw, as expected before fix)!")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
